def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a solid separator row or column.
    split = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            split = ("row", r)
            break
    if split is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                split = ("col", c)
                break

    if split[0] == "row":
        _, k = split
        a, b = grid[:k], grid[k + 1:]
    else:
        _, k = split
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    def counts(panel):
        d = {}
        for row in panel:
            for x in row:
                d[x] = d.get(x, 0) + 1
        return d

    ca, cb = counts(a), counts(b)

    # The demos use 9 as the matching mark in both panels. Otherwise,
    # use the contrasting marks, with the top panel's background shared
    # across the lower panel.
    if 9 in ca and 9 in cb:
        ma = mb = 9
    else:
        bg = max(ca, key=ca.get)
        ma = min(ca, key=ca.get)
        mb = next((x for x in cb if x != bg), min(cb, key=cb.get))

    out = [[9] * len(a[0]) for _ in range(len(a))]
    for r in range(len(a)):
        for c in range(len(a[0])):
            if a[r][c] == ma and b[r][c] == mb:
                out[r][c] = 3
    return out
