def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform separator whose color does not occur elsewhere.
    sep = None
    for r in range(h):
        color = grid[r][0]
        if all(x == color for x in grid[r]):
            outside = [grid[i][j] for i in range(h) if i != r for j in range(w)]
            if color not in outside:
                sep = ("row", r, color)
                break

    if sep is None:
        for c in range(w):
            color = grid[0][c]
            if all(grid[r][c] == color for r in range(h)):
                outside = [grid[i][j] for i in range(h) for j in range(w) if j != c]
                if color not in outside:
                    sep = ("col", c, color)
                    break

    if sep[0] == "row":
        k = sep[1]
        a, b = grid[:k], grid[k + 1:]
    else:
        k = sep[1]
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    common = set(x for row in a for x in row) & set(x for row in b for x in row)
    background = next(iter(common))

    out = [[background] * len(a[0]) for _ in range(len(a))]
    for r in range(len(a)):
        for c in range(len(a[0])):
            if a[r][c] == background and b[r][c] == background:
                out[r][c] = 3
    return out
